+    /// Welcome IDs fit completely in the existing inline prefix.
+    pub(crate) fn integer(value: u64) -> Self {
+        Self::prefixed(Bytes::new(), |e| {
+            e.u64(value).expect("uint64 fits in nine bytes");
+        })
+    }
